#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    if(scanf("%d", &n) != 1) return 0;

    vector<int> dp(n + 1, INT_MAX);
    dp[0] = 0;

    for(int i = 1; i <= n; i++){
        int x = i;
        int best = INT_MAX;
        while(x > 0){
            int d = x % 10;
            x /= 10;
            if(d > 0 && dp[i - d] < best)
                best = dp[i - d];
        }
        dp[i] = best + 1;
    }

    printf("%d\n", dp[n]);
    return 0;
}
